<?php
require __DIR__.'/../bootstrap.php';ensure_cms_schema();$slug=trim((string)getv('slug',''));$st=db()->prepare('SELECT * FROM cms_categories WHERE slug=? LIMIT 1');$st->execute([$slug]);$cat=$st->fetch();if(!$cat){http_response_code(404);exit('Category not found.');}$ps=db()->prepare("SELECT p.*,u.full_name author_name FROM cms_posts p INNER JOIN cms_post_categories pc ON pc.post_id=p.id LEFT JOIN users u ON u.id=p.author_id WHERE pc.category_id=? AND p.post_type='post' AND p.status='published' AND p.visibility='public' ORDER BY COALESCE(p.published_at,p.updated_at) DESC");$ps->execute([$cat['id']]);$posts=$ps->fetchAll();public_header($cat['name']);?><section class="about-section cms-archive"><div class="eyebrow">CATEGORY</div><h1><?=e($cat['name'])?></h1><?php if(!empty($cat['description'])):?><p><?=nl2br(e($cat['description']))?></p><?php endif;?><?php if($posts):?><div class="cms-archive-list"><?php foreach($posts as $p):?><article class="card cms-archive-item"><h2><a href="/posts/?slug=<?=urlencode($p['slug'])?>"><?=e($p['title'])?></a></h2><small>By <?=e($p['author_name']?:'PocketCat')?> · <?=e(date('M j, Y',strtotime($p['published_at']?:$p['updated_at'])))?></small><p><?=e(mb_strimwidth(trim(strip_tags($p['excerpt']?:$p['content'])),0,220,'…'))?></p></article><?php endforeach;?></div><?php else:?><p class="muted">No published posts in this category yet.</p><?php endif;?></section><?php public_footer();
